import { cn } from '@/lib/utils';

interface PaginationProps extends React.ComponentPropsWithoutRef<'nav'> {
  ref?: React.Ref<HTMLElement>;
  block?: boolean;
}

interface PaginationPreviousProps extends React.ComponentPropsWithoutRef<'div'> {
  ref?: React.Ref<HTMLDivElement>;
}

interface PaginationNextProps extends React.ComponentPropsWithoutRef<'div'> {
  ref?: React.Ref<HTMLDivElement>;
}

interface PaginationListProps extends React.ComponentPropsWithoutRef<'ul'> {
  ref?: React.Ref<HTMLUListElement>;
}

interface PaginationItemProps extends React.ComponentPropsWithoutRef<'li'> {
  ref?: React.Ref<HTMLLIElement>;
  current?: boolean;
}

interface PaginationEllipsisProps extends React.ComponentPropsWithoutRef<'li'> {
  ref?: React.Ref<HTMLLIElement>;
}

interface PaginationLinkProps extends React.ComponentPropsWithoutRef<'a'> {
  ref?: React.Ref<HTMLAnchorElement>;
}

interface PaginationLinkTitleProps extends React.ComponentPropsWithoutRef<'span'> {
  ref?: React.Ref<HTMLSpanElement>;
  decorated?: boolean;
}

interface PaginationLinkLabelProps extends React.ComponentPropsWithoutRef<'span'> {
  ref?: React.Ref<HTMLSpanElement>;
}

const PrevArrow = () => (
  <svg
    className='govuk-pagination-icon mr-govuk-3 fill-current'
    xmlns='http://www.w3.org/2000/svg'
    height='13'
    width='15'
    aria-hidden='true'
    focusable='false'
    viewBox='0 0 15 13'
  >
    <path d='m6.5938-0.0078125-6.7266 6.7266 6.7441 6.4062 1.377-1.449-4.1856-3.9768h12.896v-2h-12.984l4.2931-4.293-1.414-1.414z' />
  </svg>
);

const NextArrow = () => (
  <svg
    className='govuk-pagination-icon ml-govuk-3 fill-current'
    xmlns='http://www.w3.org/2000/svg'
    height='13'
    width='15'
    aria-hidden='true'
    focusable='false'
    viewBox='0 0 15 13'
  >
    <path d='m8.107-0.0078125-1.4136 1.414 4.2926 4.293h-12.986v2h12.896l-4.1855 3.9766 1.377 1.4492 6.7441-6.4062-6.7246-6.7266z' />
  </svg>
);

const Pagination = ({
  className,
  block,
  children,
  ref,
  ...props
}: PaginationProps) => (
  <nav
    ref={ref}
    className={cn(
      'font-govuk mb-govuk-6 flex flex-col flex-wrap items-center',
      'md:flex-row md:items-start',
      block && 'govuk-pagination-block',
      className,
    )}
    aria-label={props['aria-label'] ?? 'Pagination'}
    {...props}
  >
    {children}
  </nav>
);

const PaginationPrevious = ({
  className,
  children,
  ref,
  ...props
}: PaginationPreviousProps) => (
  <div
    ref={ref}
    className={cn(
      'govuk-pagination-nav-item box-border relative',
      'min-w-govuk-pagination-touch min-h-govuk-pagination-touch',
      'py-govuk-2 px-govuk-3 pl-0 float-left font-bold text-govuk-body',
      className,
    )}
    {...props}
  >
    {children}
  </div>
);

const PaginationNext = ({
  className,
  children,
  ref,
  ...props
}: PaginationNextProps) => (
  <div
    ref={ref}
    className={cn(
      'govuk-pagination-nav-item box-border relative',
      'min-w-govuk-pagination-touch min-h-govuk-pagination-touch',
      'py-govuk-2 px-govuk-3 pr-0 float-left font-bold text-govuk-body',
      className,
    )}
    {...props}
  >
    {children}
  </div>
);

const PaginationList = ({
  className,
  children,
  ref,
  ...props
}: PaginationListProps) => (
  <ul ref={ref} className={cn('m-0 p-0 list-none', className)} {...props}>
    {children}
  </ul>
);

const PaginationItem = ({
  className,
  current,
  children,
  ref,
  ...props
}: PaginationItemProps) => (
  <li
    ref={ref}
    className={cn(
      'govuk-pagination-item box-border relative',
      'min-w-govuk-pagination-touch min-h-govuk-pagination-touch',
      'py-govuk-2 px-govuk-3 float-left text-center text-govuk-body',
      'hidden first:block last:block md:block',
      current && 'block font-bold govuk-pagination-item-current',
      className,
    )}
    {...props}
  >
    {children}
  </li>
);

const PaginationEllipsis = ({
  className,
  ref,
  ...props
}: PaginationEllipsisProps) => (
  <li
    ref={ref}
    className={cn(
      'govuk-pagination-item box-border relative',
      'min-w-govuk-pagination-touch min-h-govuk-pagination-touch',
      'py-govuk-2 px-govuk-3 float-left text-center text-govuk-body',
      'block font-bold text-govuk-dark-grey',
      'hover:bg-transparent',
      className,
    )}
    {...props}
  >
    &ctdot;
  </li>
);

const PaginationLink = ({
  className,
  children,
  ref,
  ...props
}: PaginationLinkProps) => (
  <a
    ref={ref}
    className={cn(
      'govuk-pagination-link block min-w-govuk-3',
      'text-govuk-brand no-underline govuk-link-underline',
      'hover:text-govuk-brand-hover hover:govuk-link-underline-hover',
      'visited:text-govuk-visited',
      'focus:govuk-link-focus',
      className,
    )}
    {...props}
  >
    {children}
  </a>
);

const PaginationLinkTitle = ({
  className,
  decorated,
  children,
  ref,
  ...props
}: PaginationLinkTitleProps) => (
  <span
    ref={ref}
    className={cn(
      'decoration-inherit',
      decorated && 'underline govuk-link-underline',
      className,
    )}
    {...props}
  >
    {children}
  </span>
);

const PaginationLinkLabel = ({
  className,
  children,
  ref,
  ...props
}: PaginationLinkLabelProps) => (
  <span
    ref={ref}
    className={cn(
      'font-normal underline govuk-link-underline inline-block',
      className,
    )}
    {...props}
  >
    {children}
  </span>
);

export {
  Pagination,
  PaginationPrevious,
  PaginationNext,
  PaginationList,
  PaginationItem,
  PaginationEllipsis,
  PaginationLink,
  PaginationLinkTitle,
  PaginationLinkLabel,
  PrevArrow,
  NextArrow,
};

export type {
  PaginationProps,
  PaginationPreviousProps,
  PaginationNextProps,
  PaginationListProps,
  PaginationItemProps,
  PaginationEllipsisProps,
  PaginationLinkProps,
  PaginationLinkTitleProps,
  PaginationLinkLabelProps,
};
